export function CustomView({
  viewType = "{{viewType}}",
  accent = "{{accent}}",
  showCount = {{showCount}},
  viewName = "{{viewName}}",
}) {
  const rows = [["Acme Co", "$4,200"], ["Globex", "$1,800"], ["Initech", "$9,050"]];
  return (
    <div style={{ font: "12px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 16, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 12px", fontWeight: 700 }}>&#9733; {viewName}{showCount && <span style={{ fontSize: 10, color: "#24143099", fontWeight: 400 }}> 3</span>}</p>
      {viewType === "table" && (
        <table style={{ width: "100%", borderCollapse: "collapse" }}>
          <tbody>{rows.map(([n, v]) => <tr key={n}><td style={{ padding: "6px 4px", borderBottom: "1px solid #24143014" }}>{n}</td><td style={{ padding: "6px 4px", borderBottom: "1px solid #24143014" }}>{v}</td></tr>)}</tbody>
        </table>
      )}
      {viewType === "cards" && (
        <div style={{ display: "flex", gap: 8 }}>
          {rows.map(([n, v]) => <div key={n} style={{ flex: 1, padding: 10, borderRadius: 8, background: "#ffffff", border: "1px solid #24143018", borderTop: `4px solid ${accent}`, textAlign: "center" }}>{n}<b style={{ display: "block", marginTop: 4 }}>{v}</b></div>)}
        </div>
      )}
      {viewType === "list" && (
        <ul style={{ listStyle: "none", margin: 0, padding: 0 }}>
          {rows.map(([n, v]) => <li key={n} style={{ display: "flex", alignItems: "center", gap: 8, padding: "6px 0" }}><span style={{ width: 8, height: 8, borderRadius: "50%", flexShrink: 0, background: accent }} />{n} &mdash; {v}</li>)}
        </ul>
      )}
    </div>
  );
}
